	using namespace noarr;

	// spatial problem size
	auto n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Tunable block size for the i-dimension. We use into_blocks_dynamic to
	// avoid any requirement that (n-2) must be divisible by i_block_size;
	// the extra 'p' dimension internally masks out padded elements in the
	// final (possibly partial) block.
	constexpr std::size_t i_block_size = tuning::i_block_size;

