// Simple tuning container:
// - layout proto-structures are kept unchanged
// - we additionally provide a tunable spatial blocking factor
struct tuning {
	// Spatial blocking size for the 'i' dimension.
	// This only affects traversal order (via into_blocks) and does
	// not change the logical problem size. It can be tuned for
	// particular cache hierarchies.
	static constexpr std::size_t i_block = 256;

	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// initialization function
void init_array(auto A, auto B) {
	using namespace noarr;

	// Spatial problem size (same for both A and B)
	const std::size_t n = A | get_length<'i'>();
	const num_t inv_n = static_cast<num_t>(1) / static_cast<num_t>(n);

	traverser(A, B).for_each([=](auto state) {
		const auto i = get_index<'i'>(state);
		const num_t fi = static_cast<num_t>(i);

		// Use multiplication by precomputed 1/n for better codegen
		A[state] = (fi + static_cast<num_t>(2)) * inv_n;
		B[state] = (fi + static_cast<num_t>(3)) * inv_n;
	});
}

// computation kernel
//
// We keep the mathematical scheme identical:
//
//   for t = 0 .. tsteps-1:
//     for i = 1 .. n-2:  B[i] = 1/3 * (A[i-1] + A[i] + A[i+1])
//     for i = 1 .. n-2:  A[i] = 1/3 * (B[i-1] + B[i] + B[i+1])
//
// but we improve traversal and constant handling:
//   - prebuild traversers and reuse them for every time step
//   - use a blocked spatial traversal (into_blocks_static) to give
//     the compiler an explicit strip-mined loop structure that can
//     be tuned via tuning::i_block
//   - keep access through Noarr bags and index states
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	const std::size_t n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// constant stencil coefficient (kept in a local variable so that
	// conversions are done once and the compiler can reuse it)
	constexpr num_t coeff = static_cast<num_t>(0.33333);

	// -----------------------------------------------------------------
	// Spatial traversal order
	// -----------------------------------------------------------------
	// First, select interior points i in [1, n-2].
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Then, split the interior domain into blocks along 'i' using
	// into_blocks_static. This is a pure traversal transformation:
	// it does not change which elements are updated, only the order.
	//
	// Dimensions in into_blocks_static:
	//   - Dim      = 'i'  : original dimension
	//   - DimIsBorder = 'b': distinguishes body vs. border blocks
	//   - DimMajor = 'I'  : block index along 'i'
	//   - DimMinor = 'i'  : index inside a block (we reuse the name 'i')
	//
	// We use tuning::i_block as the block size. The use of lit<> makes
	// the block size a compile-time constant, but the leftover (border)
	// elements are still handled correctly by into_blocks_static.
	auto spatial_blocked =
		interior ^
		noarr::into_blocks_static<'i', 'b', 'I', 'i'>(noarr::lit<tuning::i_block>);

	// Prebuild traversers for both sweeps with the same blocked order.
	// Thanks to traverser(...).order(...), the states passed to the
	// lambdas still only contain the original dimension 'i'; the extra
	// blocking dimensions ('b', 'I') are internal to the traverser.
	auto trav_B_from_A = traverser(B, A).order(spatial_blocked);
	auto trav_A_from_B = traverser(A, B).order(spatial_blocked);

