#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/traverser_iter.hpp>   // range-based traverser iteration (used with OpenMP)
#include <noarr/structures/interop/serialize_data.hpp>   // explicit for serialize_data

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

namespace {

// ---------------------------------------------------------------------------
// Problem layout
// ---------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();

// The tuning struct is kept as in the original code, but can be extended if
// needed (e.g., for alternative data layouts).
struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// ---------------------------------------------------------------------------
// Parallel traversal helper
// ---------------------------------------------------------------------------

// Tunable OpenMP chunk size for the outermost traverser dimension.
//
// The traverser iterator exposes the outermost dimension as a range.
// We use a static schedule with this chunk size so each thread gets
// approximately this many elements at a time, which allows adaptation
// to different cache / NUMA characteristics of the target machine.
constexpr int JACOBI_OMP_CHUNK_I = 1024;

// Run `f` on every element described by `trav` in parallel using OpenMP.
// The iteration space itself is still expressed purely via Noarr traversers.
template<class Trav, class Func>
inline void omp_trav_for_each(const Trav &trav, const Func &f) {
	#pragma omp parallel for schedule(static, JACOBI_OMP_CHUNK_I)
	for (auto subtrav : trav) {
		// `subtrav` has the outermost dimension fixed. For a 1D structure this
		// means a single element; for higher dimensions this can represent a
		// whole line/slice. We then let Noarr iterate the remaining dimensions.
		subtrav.for_each(f);
	}
}

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

void init_array(auto A, auto B) {
	using namespace noarr;

	// Spatial problem size (computed once instead of inside the lambda)
	const auto n = A | get_length<'i'>();

	traverser(A, B).for_each([=](auto state) {
		const auto i = get_index<'i'>(state);

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2)) / static_cast<num_t>(n);
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3)) / static_cast<num_t>(n);
	});
}

// ---------------------------------------------------------------------------
// Computation kernel
// ---------------------------------------------------------------------------
//
// Jacobi 1D (3‑point stencil), PolyBench style:
//
// for (t = 0; t < T; t++) {
//   for (i = 1; i < N-1; i++)
//     B[i] = c * (A[i-1] + A[i] + A[i+1]);
//   for (i = 1; i < N-1; i++)
//     A[i] = c * (B[i-1] + B[i] + B[i+1]);
// }
//
// We keep the exact semantics (two sweeps per outer time iteration) but
// parallelize each spatial sweep over 'i' using Noarr traversers plus
// an OpenMP parallel-for over the outermost traverser dimension.

[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// Spatial problem size
	const auto n = A | get_length<'i'>();

	// Structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// View selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Pre-build traversers for the two sweeps, ordered to only visit the
	// interior part. This avoids reconstructing them in every time step.
	auto trav_B_from_A = traverser(B, A).order(interior);
	auto trav_A_from_B = traverser(A, B).order(interior);

	// Stencil coefficient, hoisted out of the loops
	constexpr num_t c = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// -------------------------------------------------------------------
		// First sweep: update B from A
		// -------------------------------------------------------------------
		//
		// We parallelize the spatial sweep along 'i'. The traversal order is
		// still defined purely by Noarr; OpenMP only splits the outer-most
		// dimension among threads.

		omp_trav_for_each(trav_B_from_A, [=](auto state) {
			// All arithmetic is done on the index state; the actual access
			// is always `A[state]` / `B[state]` as required.
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			B[state] = c * (A[left] + A[state] + A[right]);
		});

		// -------------------------------------------------------------------
		// Second sweep: update A from B
		// -------------------------------------------------------------------

		omp_trav_for_each(trav_A_from_B, [=](auto state) {
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			A[state] = c * (B[left] + B[state] + B[right]);
		});
	});
