struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// initialization function
void init_array(auto A, auto B) {
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		auto n = A | get_length<'i'>();

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2)) / static_cast<num_t>(n);
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3)) / static_cast<num_t>(n);
	});
}

// computation kernel
//
// Optimized with:
//  - blocked traversal in the spatial dimension `i` using `into_blocks_static`,
//    which produces an explicit outer "block" loop and an inner contiguous loop.
//    This improves cache behavior and helps the compiler vectorize the innermost loop.
//  - reuse of prepared traversers across time steps (only the time dimension is
//    iterated separately).
//
// Semantics are unchanged: two Jacobi sweeps per time step, using only values
// from the previous sweep (true Jacobi, not Gauss–Seidel).
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	auto n = A | get_length<'i'>();

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// Tunable spatial block size (number of interior points per block).
	// Must be > 0; no requirement that (n - 2) is divisible by this value.
	// You can change this constant to retune for a specific machine.
	constexpr std::size_t I_BLOCK_SIZE = 256;

	using noarr::lit;

	// Blocked view of the interior:
	//  - first slice away the boundary points,
	//  - then split dimension 'i' into:
	//      * 'I'  : block index (major dimension)
	//      * 'd'  : index within the block (minor dimension)
	//      * 'b'  : body/border flag (tuple-like dimension; 0 = full blocks,
	//                                    1 = last, possibly partial block)
	//
	// `into_blocks_static` takes care of non-divisible lengths, putting the
	// remainder into the border part. When used via `order(...)` the traverser
	// still exposes only the original dimension 'i' in the state; the block
	// structure affects *only* the traversal order and loop nesting, not the
	// indexing API seen in this kernel.
	auto blocked_interior =
		interior ^ noarr::into_blocks_static<'i', 'b', 'I', 'd'>(lit<I_BLOCK_SIZE>);

	// Pre-build traversers for the two sweeps, reusing the same blocked order
	// for every time step. States produced by these traversers still contain
	// only the original dimension 'i', so neighbor computations via +/- idx<'i'>
	// remain exactly the same as in the baseline code.
	auto trav_B_from_A = traverser(B, A).order(blocked_interior);
	auto trav_A_from_B = traverser(A, B).order(blocked_interior);

	const num_t coeff = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([&](auto /*t_state*/) {
		// first sweep: update B from A
		trav_B_from_A.for_each([&](auto state) {
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			B[state] = coeff * (A[left] + A[state] + A[right]);
		});

		// second sweep: update A from B
		trav_A_from_B.for_each([&](auto state) {
			auto left  = state - noarr::idx<'i'>(1);
			auto right = state + noarr::idx<'i'>(1);

			A[state] = coeff * (B[left] + B[state] + B[right]);
		});
	});
	#pragma endscop
}

